<?php
require_once 'config/app.php';require_roles(['admin','operator']);$pageTitle='Pengembalian Kendaraan';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['peminjaman_id'];$q=$pdo->prepare("SELECT * FROM peminjaman WHERE id=? AND status IN ('Disetujui','Sedang Digunakan')");$q->execute([$id]);$p=$q->fetch();if($p){try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO pengembalian(peminjaman_id,tanggal_kembali,kilometer_awal,kilometer_akhir,kondisi_kendaraan,jumlah_bbm,catatan,petugas_penerima) VALUES(?,?,?,?,?,?,?,?)");$q->execute([$id,$_POST['tanggal_kembali'],$_POST['kilometer_awal']?:null,$_POST['kilometer_akhir']?:null,$_POST['kondisi_kendaraan'],trim($_POST['jumlah_bbm']),trim($_POST['catatan']),current_user()['nama']]);$pdo->prepare("UPDATE peminjaman SET status='Selesai' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE kendaraan SET status=? WHERE id=?")->execute([$_POST['kondisi_kendaraan']==='Baik'?'Tersedia':'Perawatan',$p['kendaraan_id']]);log_status($pdo,$id,$p['status'],'Selesai','Kendaraan dikembalikan');$pdo->commit();flash('Pengembalian berhasil dicatat.');}catch(Throwable $e){$pdo->rollBack();flash('Gagal menyimpan pengembalian: '.$e->getMessage(),'danger');}}redirect('pengembalian.php');}
$active=$pdo->query("SELECT p.*,g.nama,k.merk,k.nomor_polisi FROM peminjaman p JOIN pegawai g ON g.id=p.pegawai_id JOIN kendaraan k ON k.id=p.kendaraan_id WHERE p.status IN ('Disetujui','Sedang Digunakan') ORDER BY p.tanggal_pinjam")->fetchAll();$done=$pdo->query("SELECT r.*,p.nomor_peminjaman,g.nama,k.nomor_polisi FROM pengembalian r JOIN peminjaman p ON p.id=r.peminjaman_id JOIN pegawai g ON g.id=p.pegawai_id JOIN kendaraan k ON k.id=p.kendaraan_id ORDER BY r.id DESC LIMIT 15")->fetchAll();require 'includes/header.php';?>
<h3 class="mb-3">Pengembalian Kendaraan</h3><div class="card mb-4"><div class="card-header bg-white fw-bold">Kendaraan yang masih dipinjam</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>No. Pengajuan</th><th>Peminjam</th><th>Kendaraan</th><th>Rencana Kembali</th><th>Catat Pengembalian</th></tr></thead><tbody><?php foreach($active as $r):?><tr><td><?=e($r['nomor_peminjaman'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['merk'].' / '.$r['nomor_polisi'])?></td><td><?=e(date('d-m-Y H:i',strtotime($r['tanggal_kembali_rencana'])))?></td><td><button class="btn btn-sm btn-primary" data-bs-toggle="collapse" data-bs-target="#ret<?=$r['id']?>">Input</button></td></tr><tr class="collapse" id="ret<?=$r['id']?>"><td colspan="5"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="peminjaman_id" value="<?=$r['id']?>"><div class="col-md-3"><label class="form-label">Tanggal Kembali</label><input type="datetime-local" name="tanggal_kembali" class="form-control" required value="<?=date('Y-m-d\TH:i')?>"></div><div class="col-md-2"><label class="form-label">KM Awal</label><input type="number" name="kilometer_awal" class="form-control"></div><div class="col-md-2"><label class="form-label">KM Akhir</label><input type="number" name="kilometer_akhir" class="form-control"></div><div class="col-md-2"><label class="form-label">Kondisi</label><select name="kondisi_kendaraan" class="form-select"><option>Baik</option><option>Rusak Ringan</option><option>Rusak Berat</option></select></div><div class="col-md-3"><label class="form-label">BBM</label><input name="jumlah_bbm" class="form-control" placeholder="Mis. 1/2 tangki"></div><div class="col-md-9"><label class="form-label">Catatan</label><input name="catatan" class="form-control"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-success">Simpan Pengembalian</button></div></form></td></tr><?php endforeach;?><?php if(!$active):?><tr><td colspan="5" class="text-center p-3">Tidak ada kendaraan yang sedang dipinjam.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header bg-white fw-bold">Riwayat Pengembalian Terakhir</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nomor</th><th>Peminjam</th><th>Nomor Polisi</th><th>Tanggal Kembali</th><th>Kondisi</th></tr></thead><tbody><?php foreach($done as $r):?><tr><td><?=e($r['nomor_peminjaman'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['nomor_polisi'])?></td><td><?=e(date('d-m-Y H:i',strtotime($r['tanggal_kembali'])))?></td><td><?=e($r['kondisi_kendaraan'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>